function uniqueCards(cards) {
  const seen = new Set();
  return cards.filter(([label, image]) => {
    if (seen.has(image)) return false;
    seen.add(image);
    return true;
  });
}

const isPlaceholderModel = (model) => !model || /^(verify model|unknown model|model to be confirmed)$/i.test(String(model).trim());
const modelTokens = (model) => String(model || '').toLowerCase().split(/[,/;|]+/).map((value) => value.replace(/[^a-z0-9]+/g, '')).filter(Boolean);
const modelMatches = (candidate, requested) => {
  if (isPlaceholderModel(candidate) || isPlaceholderModel(requested)) return false;
  const left = modelTokens(candidate);
  const right = modelTokens(requested);
  return right.some((token) => left.includes(token)) || left.some((token) => right.includes(token));
};
const modelLabel = (item) => isPlaceholderModel(item?.model) ? (item?.name || 'Product model to be confirmed') : item.model;
const usableModels = (items) => items.filter((item) => !isPlaceholderModel(item?.model));
const familyLabel = (family) => ({ Pumps: 'Hydraulic Pumps', Motors: 'Hydraulic Motors', Valves: 'Hydraulic Valves', 'Pneumatic Valves': 'Pneumatic Valves', Cylinders: 'Cylinders & Actuators', 'Solenoid Valves': 'Solenoid Valves' }[family] || family);

function ProductGroupModal({ items, onClose, onSelect }) {
  return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}>
    <section className="modal model-group-modal" role="dialog" aria-modal="true" aria-labelledby="model-group-title">
      <button className="icon-button modal-close" onClick={onClose} aria-label="Close model list"><X size={20} /></button>
      <div className="modal-kicker">ONE IMAGE / {items.length} MODELS</div>
      <h2 id="model-group-title">Select a model</h2>
      <p className="model-group-intro">These models share the same product image. Choose the exact model to open its inquiry.</p>
      <div className="model-group-list">{usableModels(items).map((item) => <button type="button" className="model-group-item" key={`${item.model}-${item.productId || item.sourceTitle}`} onClick={() => onSelect(item)}><span><b>{modelLabel(item)}</b><small>{item.name}</small></span><ArrowUpRight size={18} /></button>)}</div>
    </section>
  </div>;
}

function InquiryModal({ product, onClose, copy = COPY.en }) {
  const [status, setStatus] = useState('idle');
  const submit = async (event) => {
    event.preventDefault();
    setStatus('sending');
    const form = new FormData(event.currentTarget);
    const data = Object.fromEntries(form.entries());
    data.attachmentName = form.get('attachment')?.name || '';
    delete data.attachment;
    try {
      const response = await fetch('/api/inquiry', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
      if (!response.ok) throw new Error('request failed');
      setStatus('sent');
    } catch { setStatus('error'); }
  };
  return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}>
    <section className="modal" role="dialog" aria-modal="true" aria-labelledby="inquiry-title">
      <button className="icon-button modal-close" onClick={onClose} aria-label="Close inquiry"><X size={20} /></button>
      <div className="modal-kicker">PRODUCT INQUIRY / {product?.model || 'GENERAL REQUEST'}</div>
      <h2 id="inquiry-title">{copy.inquiryTitle}</h2>
      {status === 'sent' ? <div className="success-state"><ShieldCheck size={34} /><h3>Inquiry received.</h3><p>Your request has been recorded for follow-up. The receiving mailbox is currently set to wxldpack@gmail.com.</p><button className="button primary" onClick={onClose}>Close <ArrowUpRight size={16} /></button></div> : <form onSubmit={submit} className="inquiry-form">
        <input type="hidden" name="product" value={product?.model || ''} /><input type="hidden" name="sourceTitle" value={product?.sourceTitle || product?.name || ''} />
        <div className="form-grid"><label>Name<input name="name" required placeholder="Your name" /></label><label>Company<input name="company" placeholder="Company name" /></label></div>
        <div className="form-grid"><label>Work email<input name="email" type="email" required placeholder="you@company.com" /></label><label>WhatsApp / phone<input name="phone" placeholder="Country code + number" /></label></div>
        <div className="form-grid"><label>Quantity<input name="quantity" placeholder="e.g. 2 pcs" /></label><label>Destination<input name="destination" placeholder="Country / port" /></label></div>
        <label>Requirement<textarea name="message" required rows="4" placeholder="Machine model, part number, application, target delivery..."></textarea></label>
        <label className="upload-box"><Upload size={18} /><span>Attach nameplate or product photo <small>JPG, PNG or WEBP · one file</small></span><input name="attachment" type="file" accept="image/jpeg,image/png,image/webp" /></label>
        {status === 'error' && <p className="form-error">The request could not be sent. Please contact wxldpack@gmail.com or use WhatsApp.</p>}
        <button className="button primary" disabled={status === 'sending'}>{status === 'sending' ? 'Sending…' : 'Send inquiry'} <ArrowUpRight size={16} /></button>
      </form>}
    </section>
  </div>;
}

