function ProductDetailPage({ language, setLanguage, t }) {
  const location = useLocation();
  const [selected, setSelected] = useState(null);
  const params = new URLSearchParams(location.search);
  const modelQuery = params.get('model') || '';
  const imageQuery = params.get('image') || '';
  const matchingProducts = productsWithImages.filter((product) => !isPlaceholderModel(modelQuery) && (modelMatches(product.model, modelQuery) || product.variants?.some((variant) => modelMatches(variant.model, modelQuery))));
  const parent = matchingProducts.find((product) => imageQuery && product.image === imageQuery) || matchingProducts.find((product) => product.gallery?.length) || productsWithImages.find((product) => imageQuery && product.image === imageQuery) || matchingProducts[0] || productsWithImages[0];
  const variant = modelMatches(parent?.model, modelQuery) ? parent : parent?.variants?.find((item) => modelMatches(item.model, modelQuery)) || parent;
  const product = { ...parent, ...variant, image: parent?.image, family: parent?.family, fit: variant?.fit || parent?.fit, sourceTitle: variant?.sourceTitle || parent?.sourceTitle };
  const visibleModel = modelLabel(product);
  const whatsappText = encodeURIComponent(`Hello SUNSHINE PARTS, I would like a quotation for ${visibleModel}.`);
  const relatedProducts = productsWithImages.filter((item) => item.family === product.family && item.image !== product.image && item.model !== product.model).slice(0, 4);
  const galleryImages = [product.image, ...(product.gallery || [])].filter(Boolean).filter((image, index, list) => list.indexOf(image) === index).slice(0, 6);
  const specRows = [['Product family', product.family], ['Model / series', visibleModel], ['Application', product.fit || 'Confirm with inquiry'], ['MOQ', product.moq || 'Confirm with inquiry'], ['FOB price', product.price || 'Price on request'], ['Source reference', product.sourceTitle || 'SUNSHINE PARTS catalog']];
  const familyOverview = {
    Pumps: { title: 'Hydraulic pumps', image: '/assets/images/category-pump-representative.png', text: 'Pump selection depends on model, displacement, pressure, control details, mounting and the machine application.' },
    Motors: { title: 'Hydraulic motors', image: '/assets/images/category-pump-representative.png', text: 'Motor selection should be checked against the machine model, displacement, mounting, shaft and operating conditions.' },
    Valves: { title: 'Hydraulic valves', image: '/assets/images/category-hydraulic-valve-representative.png', text: 'Valve matching depends on function, interface, control method, pressure range and the existing hydraulic system.' },
    'Solenoid Valves': { title: 'Solenoid valves', image: '/assets/images/category-pneumatic-valve-representative.png', text: 'Confirm voltage, port size, function, medium and installation requirements before quotation.' },
    'Pneumatic Valves': { title: 'Pneumatic valves', image: '/assets/images/category-pneumatic-valve-representative.png', text: 'Pneumatic valve selection should be checked against circuit function, port details, pressure and the working medium.' },
    Cylinders: { title: 'Cylinders & actuators', image: '/assets/images/category-cylinder-representative.png', text: 'Cylinder and actuator matching depends on bore, stroke, mounting, operating pressure and the machine application.' }
  }[product.family] || { title: product.family || 'Industrial component', image: product.image, text: 'Share the model, application and available technical information so the selected component can be reviewed accurately.' };
  const detailFaqs = [
    [`How do I confirm ${visibleModel}?`, 'Send the model number, brand, nameplate photo and machine application. Final fit should be confirmed against the selected equipment and interface.'],
    ['What information should be included in a quotation request?', 'Include quantity, destination, application and any available drawing, product image or nameplate photo.'],
    ['Can you provide more models or brands?', 'The catalog contains multiple product families and source records. Send your requirement and we will review the available matching route.'],
    ['Are all specifications shown on this page final?', 'Only values available in the current product record are shown. Missing technical, commercial or document details should be confirmed through inquiry.']
  ];
  return <div className="site-shell"><SiteHeader language={language} setLanguage={setLanguage} t={t} /><main className="product-detail-page"><div className="detail-breadcrumb"><Link to="/products">Products</Link><span>›</span><span>{product.family}</span><span>›</span><strong>{visibleModel}</strong></div><section className="detail-hero"><div className="detail-gallery"><div className="detail-visual"><img src={galleryImages[0]} alt={`${visibleModel} ${product.name}`} onError={(event) => { event.currentTarget.src = '/assets/images/placeholder.svg'; }} /><span className="detail-visual-label">SUNSHINE PARTS · {product.imageType === 'representative' ? 'CATEGORY REPRESENTATIVE' : 'ACTUAL PRODUCT IMAGE'}</span></div>{galleryImages.length > 1 && <div className="detail-thumbnails">{galleryImages.map((image, index) => <button type="button" key={image} className={index === 0 ? 'active' : ''} onClick={(event) => { const hero = event.currentTarget.closest('.detail-gallery').querySelector('.detail-visual img'); hero.src = image; event.currentTarget.parentElement.querySelectorAll('button').forEach((button) => button.classList.remove('active')); event.currentTarget.classList.add('active'); }}><img src={image} alt={`${visibleModel} view ${index + 1}`} /></button>)}</div>}</div><div className="detail-summary"><div className="eyebrow amber"><span></span> {product.family?.toUpperCase()} / PRODUCT DETAIL</div><h1>{product.name || product.model}</h1><h2>{visibleModel}</h2><p className="detail-lead">Factory-direct {product.family?.toLowerCase()} component for {product.fit || 'industrial and mobile machinery applications'}.</p><div className="detail-pills"><span>MOQ: {product.moq || 'On request'}</span><span>FOB: {product.price || 'On request'}</span></div><dl className="detail-data-panel">{specRows.map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value || 'Not provided'}</dd></div>)}</dl><div className="detail-ctas"><a className="button whatsapp" href={`https://wa.me/${WHATSAPP}?text=${whatsappText}`} target="_blank" rel="noreferrer"><MessageCircle size={17} /> {t.whatsapp}</a><button className="button primary" onClick={() => setSelected(product)}>{t.quote} <ArrowUpRight size={17} /></button></div><p className="detail-note">Send the model, quantity, destination and a nameplate photo for faster matching.</p></div></section><section className="detail-buying-bar"><div><span>BUYING FORMAT</span><b>OEM / AFTERMARKET / PROJECT</b></div><div><span>QUOTE INPUTS</span><b>MODEL · QTY · DESTINATION</b></div><div><span>CONTACT ROUTE</span><b>EMAIL / WHATSAPP / RFQ</b></div></section><section className="detail-tabs" aria-label="Product detail sections"><a href="#product-description">Product details</a><a href="#product-specification">Specification</a><a href="#product-faq">FAQ</a><a href="#supplier-information">Supplier information</a></section><section id="product-description" className="detail-section detail-description-section"><div className="detail-section-heading"><div className="eyebrow amber"><span></span> PRODUCT DESCRIPTION</div><h2>{familyOverview.title}<br /><em>for practical sourcing.</em></h2><p>{familyOverview.text}</p></div><div className="detail-description-grid"><div className="detail-description-copy"><p><strong>{product.name || visibleModel}</strong> is listed in the SUNSHINE PARTS catalog for model-led product review and quotation requests.</p><p>Use the product image, model reference and application information as a starting point. If the exact configuration is important, send a clear nameplate photo or drawing before ordering.</p><div className="detail-description-actions"><button className="button primary" onClick={() => setSelected(product)}>{t.quote} <ArrowUpRight size={16} /></button><a className="button secondary" href={`mailto:wxldpack@gmail.com?subject=${encodeURIComponent(`Inquiry for ${visibleModel}`)}`}>Email product inquiry <ArrowUpRight size={16} /></a></div></div><div className="detail-category-visual"><img src={familyOverview.image} alt={`${familyOverview.title} category representative`} /><span>Category representative · confirm exact model</span></div></div></section><section id="product-specification" className="detail-section detail-specification-section"><div className="detail-section-heading"><div className="eyebrow amber"><span></span> SPECIFICATION</div><h2>Information to review<br /><em>before quotation.</em></h2><p>Exact technical values vary by selected model and application. The current record is shown below without adding unverified values.</p></div><div className="detail-spec-table">{specRows.map(([label,value]) => <div key={label}><b>{label}</b><span>{value || 'Not provided · confirm with inquiry'}</span></div>)}</div></section><section className="detail-section detail-two-column detail-application-section"><div><div className="eyebrow amber"><span></span> APPLICATIONS</div><h2>Built around<br /><em>the machine.</em></h2></div><div><p>{product.fit || 'Share the machine model, operating conditions and installation requirements so the exact component can be confirmed.'}</p><ul className="detail-check-list"><li>Machine or system context</li><li>Model, series or nameplate photo</li><li>Quantity and destination</li><li>Interface or operating details when available</li></ul></div></section><section id="supplier-information" className="detail-section supplier-information-section"><div className="detail-section-heading"><div className="eyebrow amber"><span></span> SUPPLIER INFORMATION</div><h2>A clearer route from<br /><em>part to conversation.</em></h2></div><div className="supplier-information-grid"><article><b>01</b><h3>Catalog and model review</h3><p>Product family, model, image and source reference stay together on the detail page.</p></article><article><b>02</b><h3>Technical confirmation</h3><p>Pressure, flow, interface, material or other product-specific requirements should be confirmed for the selected model.</p></article><article><b>03</b><h3>Direct contact</h3><p>Send the requirement by RFQ, email or WhatsApp with the information already available.</p></article></div></section><section className="detail-process-section"><div className="detail-section-heading"><div className="eyebrow amber"><span></span> PRODUCTION &amp; ORDER PROCESS</div><h2>Prepare the request<br /><em>with useful context.</em></h2><p>This process explains how to organize a product inquiry. Availability, lead time and shipping terms are confirmed separately for each request.</p></div><div className="detail-process-grid"><article><b>01</b><h3>Identify</h3><p>Start with model, product family or a nameplate photo.</p></article><article><b>02</b><h3>Review</h3><p>Confirm the application, interface and available product information.</p></article><article><b>03</b><h3>Quote</h3><p>Share quantity and destination for commercial review.</p></article><article><b>04</b><h3>Coordinate</h3><p>Confirm documents, packaging and shipping details for the selected order.</p></article></div></section><section className="detail-section detail-faq-section" id="product-faq"><div className="detail-section-heading"><div className="eyebrow amber"><span></span> PRODUCT FAQ</div><h2>Questions buyers<br /><em>usually ask.</em></h2></div><div className="detail-faq-list">{detailFaqs.map(([question,answer]) => <details key={question}><summary>{question}<ChevronDown size={18} /></summary><p>{answer}</p></details>)}</div></section><section className="detail-section detail-quote-band"><div><div className="eyebrow amber"><span></span> READY TO SOURCE</div><h2>Need this exact<br /><em>component?</em></h2></div><div><p>Request a quotation with the model, quantity and destination. Our team will follow up with the relevant sourcing route.</p><button className="button primary" onClick={() => setSelected(product)}>{t.open} <ArrowUpRight size={17} /></button></div></section>{relatedProducts.length > 0 && <section className="detail-section related-products"><div className="detail-section-heading"><div className="eyebrow amber"><span></span> RELATED PRODUCTS</div><h2>More from this<br /><em>product family.</em></h2></div><div className="related-product-grid">{relatedProducts.map((item) => <Link key={`${item.model}-${item.image}`} to={`/products/detail?model=${encodeURIComponent(item.model)}&image=${encodeURIComponent(item.image)}`} className="related-product-card"><img src={item.image} alt={item.name} /><span>{item.family}</span><b>{modelLabel(item)}</b><small>{item.name}</small></Link>)}</div></section>}</main>{selected && <InquiryModal product={selected} copy={t} onClose={() => setSelected(null)} />}</div>;
}

function ProductsPage({ language, setLanguage, t }) {
  const location = useLocation();
  const navigate = useNavigate();
  const initialFamily = new URLSearchParams(location.search).get('family') || 'All';
  const [activeFamily, setActiveFamily] = useState(initialFamily);
  const [query, setQuery] = useState('');
  useEffect(() => { const familyFromUrl = new URLSearchParams(location.search).get('family') || 'All'; setActiveFamily(familyFromUrl); setShowAll(false); }, [location.search]);
  const [showAll, setShowAll] = useState(false);
  const [groupedItems, setGroupedItems] = useState(null);
  const filtered = useMemo(() => productsWithImages.filter((item) => (activeFamily === 'All' || item.family === activeFamily) && `${item.model} ${item.name} ${item.fit}`.toLowerCase().includes(query.toLowerCase())), [activeFamily, query]);
  const groups = useMemo(() => { const map = new Map(); filtered.forEach((item) => { const key = `${item.family}|${item.visualGroup || item.image || item.model}`; if (!map.has(key)) map.set(key, []); map.get(key).push(item); }); return Array.from(map, ([imageKey, items]) => { const models = usableModels(items.flatMap((item) => item.variants || [item])); const primary = items.find((item) => !isPlaceholderModel(item.model)) || items[0]; return { imageKey, items, primary, models }; }); }, [filtered]);
  const visible = showAll ? groups : groups.slice(0, 8);
  return <div className="site-shell"><SiteHeader language={language} setLanguage={setLanguage} t={t} /><main className="products-page"><div className="standalone-hero compact product-showcase-heading"><div className="product-heading-mark"><Boxes size={30} strokeWidth={1.8} /></div><div className="eyebrow amber"><span></span> B2B PRODUCT SOLUTIONS</div><h1>Hydraulic &amp; pneumatic<br /><em>components.</em></h1><p>Factory-direct pumps, valves, motors and pneumatic components organized for faster model matching and global inquiry.</p></div><div className="catalog-toolbar products-toolbar"><label className="search-box"><Search size={19} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t.search} /></label><div className="family-filters">{families.map((family) => <button type="button" key={family} className={activeFamily === family ? 'filter active' : 'filter'} onClick={() => { setActiveFamily(family); setShowAll(false); }} aria-pressed={activeFamily === family}>{familyLabel(family)}</button>)}</div></div><div className="products-result-bar"><span><b>{groups.length}</b> visual product groups</span><span>MOQ and FOB shown where available · Click a card for detail</span></div>{groups.length === 0 ? <div className="catalog-empty"><Search size={28} /><h2>No matching products yet</h2><p>Try a shorter model number, clear the family filter, or send the product image for a direct match.</p><button type="button" className="button primary" onClick={() => { setQuery(''); setActiveFamily('All'); }}>Clear filters</button></div> : <><div className="product-grid">{visible.map((group, index) => { const item=group.primary; return <article className="product-card" key={group.imageKey} onClick={() => group.models.length <= 1 ? navigate(`/products/detail?model=${encodeURIComponent((group.models[0] || item).model || '')}&image=${encodeURIComponent(item.image)}`) : setGroupedItems(group.models)}><div className="product-media"><img src={item.image} alt={`${item.model} ${item.name}`} loading={index > 2 ? 'lazy' : 'eager'} /><span className="card-index">0{index+1}</span>{group.models.length > 1 && <span className="model-count">{group.models.length} MODELS</span>}</div><div className="product-content"><div className="product-family">{item.family}</div><h3>{group.models.length > 1 ? `${modelLabel(item)} + ${group.models.length-1} more` : modelLabel(item)}</h3><p>{item.name}<br /><span>{item.fit}</span></p><div className="product-card-facts"><div><small>MOQ</small><b>{item.moq || 'On request'}</b></div><div><small>PRICE</small><b>{item.price || 'On request'}</b></div><div><small>TYPE</small><b>{item.family}</b></div></div><button className="product-card-cta" type="button">{group.models.length > 1 ? 'View all models' : 'Quote this product'} <ArrowUpRight size={15} /></button></div></article>})}</div>{groups.length > 8 && <button className="view-more-button" type="button" onClick={() => setShowAll((value) => !value)}>{showAll ? 'Show less' : 'View More'}</button>}</>}</main>{groupedItems && <ProductGroupModal items={groupedItems} onClose={() => setGroupedItems(null)} onSelect={(item) => { setGroupedItems(null); navigate(`/products/detail?model=${encodeURIComponent(item.model)}&image=${encodeURIComponent(item.image || '')}`); }} />}</div>;
}

function HomeCatalogSections({ t }) {
  const navigate = useNavigate();
  const [expanded, setExpanded] = useState({});
  const [groupedItems, setGroupedItems] = useState(null);
  const categoryGroups = useMemo(() => families.slice(1).map((family) => {
    const items = productsWithImages.filter((item) => item.family === family);
    const map = new Map();
    items.forEach((item) => {
      const key = `${family}|${item.visualGroup || item.image || item.model}`;
      if (!map.has(key)) map.set(key, []);
      map.get(key).push(item);
    });
    const groups = Array.from(map, ([imageKey, records]) => { const models = usableModels(records.flatMap((item) => item.variants || [item])); const primary = records.find((item) => !isPlaceholderModel(item.model)) || records[0]; return { imageKey, primary, models }; });
    return { family, groups };
  }).filter((section) => section.groups.length), []);
  const openDetail = (item) => navigate(`/products/detail?model=${encodeURIComponent(item.model)}${item.image ? `&image=${encodeURIComponent(item.image)}` : ''}`);
  return <section className="home-category-catalog" data-component="home-category-catalog">
    <div className="home-category-intro"><div className="product-heading-mark"><Boxes size={28} strokeWidth={1.8} /></div><div><div className="eyebrow"><span></span> B2B PRODUCT SOLUTIONS</div><h2>Explore by <em>product family.</em></h2><p>Eight representative product images per category, followed by the next category route.</p></div></div>
    {categoryGroups.map(({ family, groups }) => { const isExpanded = expanded[family]; const visible = isExpanded ? groups : groups.slice(0, 8); return <section className="home-category-block" key={family}>
      <div className="home-category-heading"><div><div className="eyebrow"><span></span> PRODUCT FAMILY</div><h3>{familyLabel(family)}</h3></div><Link to={`/products?family=${encodeURIComponent(family)}`} className="home-category-link">Open category <ArrowUpRight size={15} /></Link></div>
      <div className="product-grid">{visible.map((group, index) => { const item = group.primary; return <article className="product-card" key={group.imageKey} onClick={() => group.models.length <= 1 ? openDetail(group.models[0] || group.primary) : setGroupedItems(group.models)} role="button" tabIndex="0" onKeyDown={(event) => event.key === 'Enter' && (group.models.length <= 1 ? openDetail(group.models[0] || group.primary) : setGroupedItems(group.models))}>
        <div className="product-media"><img src={item.image} alt={`${item.model} ${item.name}`} loading="lazy" onError={(event) => { event.currentTarget.src = '/assets/images/placeholder.svg'; }} /><span className="card-index">{String(index + 1).padStart(2, '0')}</span>{group.models.length > 1 && <span className="model-count">{group.models.length} MODELS</span>}</div>
        <div className="product-content"><div className="product-family">{familyLabel(family)}</div><h3>{group.models.length > 1 ? `${modelLabel(item)} + ${group.models.length - 1} more` : modelLabel(item)}</h3><p>{item.name}<br /><span>{item.fit}</span></p><div className="product-card-facts"><div><small>PRICE</small><b>{item.price || 'On request'}</b></div><div><small>MOQ</small><b>{item.moq || 'On request'}</b></div></div><button className="product-card-cta" type="button">{group.models.length > 1 ? 'View models' : 'Open detail'} <ArrowUpRight size={15} /></button></div>
      </article>; })}</div>
      {groups.length > 8 && <button type="button" className="view-more-button" onClick={() => setExpanded((state) => ({ ...state, [family]: !isExpanded }))}>{isExpanded ? 'Show less' : 'View More'}</button>}
    </section>; })}
    {groupedItems && <ProductGroupModal items={groupedItems} onClose={() => setGroupedItems(null)} onSelect={(item) => { setGroupedItems(null); openDetail(item); }} />}
  </section>;
}
